import test from 'node:test';import assert from 'node:assert/strict';import{readFile}from'node:fs/promises';
test('recursos públicos usam caminhos portáveis',async()=>{const html=await readFile('index.html','utf8');assert.doesNotMatch(html,/(?:href|src)="\//);const manifest=JSON.parse(await readFile('public/manifest.webmanifest'));assert.equal(manifest.start_url,'./');assert.equal(manifest.scope,'./')});
test('service worker e aplicação respeitam o próprio escopo',async()=>{const [sw,main]=await Promise.all(['public/sw.js','src/main.js'].map(x=>readFile(x,'utf8')));assert.match(sw,/new URL\('\.\/index\.html',self\.location\)/);assert.doesNotMatch(main,/register\('\/sw\.js'/);assert.match(main,/official-logo\.png/)});
test('manifesto usa os ícones PNG oficiais nos tamanhos PWA',async()=>{const manifest=JSON.parse(await readFile('public/manifest.webmanifest'));assert.deepEqual(manifest.icons.map(({src,sizes,type})=>({src,sizes,type})),[{src:'./icons/icon-192.png',sizes:'192x192',type:'image/png'},{src:'./icons/icon-512.png',sizes:'512x512',type:'image/png'}])});
test('sincronização não contém credenciais fixas',async()=>{const [main,sync,server]=await Promise.all(['src/main.js','src/sync.js','google-apps-script/Code.gs'].map(x=>readFile(x,'utf8')));assert.match(main,/getSyncConfig/);assert.match(sync,/cortez-garage-sync-v1/);assert.doesNotMatch(main+sync,/1wUDxNwi1ks752davu0Aoa41yCXFWAwS/);assert.match(server,/CORTEZ_API_TOKEN/)});
test('formulário usa mecânicos predefinidos e novo checklist de entrada',async()=>{const main=await readFile('src/main.js','utf8');assert.match(main,/\['Gustavo','Cortez','Fabio'\]/);for(const item of ['Avarias na lataria','Vidros trincados ou riscados','Portas e janelas com defeito','Luz de advertência acesa','Defeito de iluminação','Buzina','Sistema de freios','Teste de rodagem'])assert.match(main,new RegExp(item));for(const oldItem of ['Retrovisores','Faróis / lanternas','Pneus','Estepe e ferramentas','Painel / quilometragem','Objetos no veículo'])assert.doesNotMatch(main,new RegExp(oldItem))});
test('Android configura sincronização e servidor compartilha arquivos',async()=>{const [activity,server]=await Promise.all(['android/app/src/main/java/com/cortezgarage/app/MainActivity.java','google-apps-script/Code.gs'].map(x=>readFile(x,'utf8')));assert.match(activity,/cortez-garage-sync-v1/);assert.match(server,/Cortez Garage - Arquivos do App/);assert.match(server,/DriveApp/)});
